using UnityEngine;using UnityEditor;using UnityEngine.Rendering.HighDefinition;using System.Linq;
public static class CaptureEntrance {public static string Main(){var src=SceneView.lastActiveSceneView.camera;var go=new GameObject("Diagnostic camera"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.CopyFrom(src);c.enabled=false;go.transform.SetPositionAndRotation(src.transform.position,src.transform.rotation);go.AddComponent<HDAdditionalCameraData>();var rt=RenderTexture.GetTemporary(1464,875,24);var prev=RenderTexture.active;var tex=new Texture2D(1464,875,TextureFormat.RGB24,false);try{c.targetTexture=rt;c.Render();c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1464,875),0,0);tex.Apply();System.IO.File.WriteAllBytes("output/Trike/Entrance.png",tex.EncodeToPNG());return string.Join("\n",Physics.OverlapBox(new Vector3(46,10,129),new Vector3(12,5,12)).Select(x=>x.name+" parent="+x.transform.parent?.name));}finally{c.targetTexture=null;RenderTexture.active=prev;RenderTexture.ReleaseTemporary(rt);Object.DestroyImmediate(go);Object.DestroyImmediate(tex);}}}
